// Prepara os dados para criar o evento
const item = $input.item.json;

const start = new Date(item.data_prevista || new Date().toISOString());
const durMin = Number(item.duracao_minutos) || 60;
const end = new Date(start.getTime() + durMin * 60 * 1000);

const body = {
  summary: item.titulo || 'Reunião ProSystem',
  start: { dateTime: start.toISOString(), timeZone: 'America/Sao_Paulo' },
  end:   { dateTime: end.toISOString(),   timeZone: 'America/Sao_Paulo' },
  conferenceData: {
    createRequest: {
      requestId: 'crm-n8n-' + Date.now(),
      conferenceSolutionKey: { type: 'hangoutsMeet' }
    }
  }
};

if (item.lead_email) {
  body.attendees = [{ email: item.lead_email }];
}

return { json: { body: JSON.stringify(body), titulo: item.titulo } };

const event = $input.item.json;

// Tenta extrair o link do Meet de diferentes formatos
const meetLink =
  event.conferenceData?.entryPoints?.find(e => e.entryPointType === 'video')?.uri ||
  event.hangoutLink ||
  '';

if (!meetLink) {
  // Loga o evento para diagnóstico
  console.error('Evento sem link Meet:', JSON.stringify(event?.conferenceData));
  // Retorna erro legível
  return {
    json: {
      success: false,
      meet_link: '',
      event_id: event.id || '',
      error: 'Link Meet não gerado. Verifique se sua conta Google tem Google Meet habilitado.'
    }
  };
}

return {
  json: {
    success: true,
    meet_link: meetLink,
    event_id: event.id || ''
  }
};
